# ছোট ৩-Document বৈজ্ঞানিক Corpus-এ Retrieval-এর মূল চুক্তি যাচাই
# Query: "vitamin c prevents common cold"
query_tokens = ["vitamin", "c", "prevents", "common", "cold"]

docs = [
    {
        "id": "101",
        "text": "vitamin c does not prevent common cold in clinical trials",
        "relevant": True,   # Claim-টিকে খণ্ডন (Refute) করলেও দারুণ Relevant Evidence!
        "stance": "REFUTES",
    },
    {
        "id": "102",
        "text": "vitamin c is found in orange and lemon juice",
        "relevant": False,  # শব্দ মিলেছে, কিন্তু Claim যাচাই করার Evidence নয়
        "stance": "IRRELEVANT",
    },
    {
        "id": "103",
        "text": "regular handwashing reduces cold virus transmission",
        "relevant": False,
        "stance": "IRRELEVANT",
    },
]

# সরল Token Overlap Similarity স্কোরিং
scored = []
query_set = set(query_tokens)
for doc in docs:
    words = doc["text"].split()
    overlap = 0
    for w in set(words):
        if w in query_set:
            overlap += 1
    score = overlap / len(query_set)
    scored.append((doc["id"], round(score, 4), doc["relevant"], doc["stance"]))

def rank_key(item):
    return (-item[1], int(item[0]))

ranked = sorted(scored, key=rank_key)
print("Top-K Ranking (id, similarity, relevant, stance):")
for pos, row in enumerate(ranked, 1):
    print(f"Rank {pos}: doc={row[0]} | sim={row[1]:.4f} | relevant={row[2]} | stance={row[3]}")

import math
import re

def ascii_tokens(text):
    # SciFact রেসিপির হুবহু Tokenizer: [A-Za-z0-9]+ ও ASCII lowercase
    raw = re.findall(r"[A-Za-z0-9]+", text)
    out = []
    for tok in raw:
        out.append(tok.lower())
    return out

corpus = [
    "BRCA1 gene mutation increases breast cancer risk",
    "cell growth and cell division in human tissue",
    "cell signaling pathway in immune cell response",
]
N = len(corpus)

# ১) Document Frequency (df) গণনা
doc_tokens = []
df = {}
for text in corpus:
    toks = ascii_tokens(text)
    doc_tokens.append(toks)
    seen = set(toks)
    for t in seen:
        df[t] = df.get(t, 0) + 1

vocab = sorted(df.keys())

# ২) Smooth IDF = 1 + ln((N + 1) / (df + 1))
idf = {}
for term in vocab:
    idf[term] = 1.0 + math.log((N + 1.0) / (df[term] + 1.0))

# ৩) Sublinear TF = 1 + ln(count) ও L2 Normalization
def build_tfidf_vector(toks):
    counts = {}
    for t in toks:
        if t in idf:
            counts[t] = counts.get(t, 0) + 1
    weights = {}
    sq_sum = 0.0
    for t, c in counts.items():
        w = (1.0 + math.log(c)) * idf[t]
        weights[t] = w
        sq_sum += w * w
    norm = math.sqrt(sq_sum)
    if norm == 0.0:
        return {}
    unit = {}
    for t, w in weights.items():
        unit[t] = w / norm
    return unit

doc_vecs = []
for toks in doc_tokens:
    doc_vecs.append(build_tfidf_vector(toks))

q_vec = build_tfidf_vector(ascii_tokens("brca1 breast cell"))

print(f"Smooth IDF('brca1')={idf['brca1']:.4f} vs IDF('cell')={idf['cell']:.4f}")
for idx, dvec in enumerate(doc_vecs):
    score = 0.0
    for t, qw in q_vec.items():
        if t in dvec:
            score += qw * dvec[t]
    print(f"Doc {idx} sparse cosine score: {score:.4f}")

# Two-stage Retrieval: First-stage Candidate Ceiling হাতে-কলমে যাচাই
relevant_docs = {"d10", "d25", "d99"}

# First-stage Bi-encoder (Top-5 Candidate Pool): d25 এবং d99 বাদ পড়েছে!
stage1_candidates = [
    ("d1", 0.88),
    ("d4", 0.82),
    ("d10", 0.79),
    ("d7", 0.75),
    ("d9", 0.71),
]

# Oracle Cross-encoder Reranker (পুলের ভেতরের প্রাসঙ্গিকগুলোকে একদম শীর্ষে তোলে!)
stage1_ids = []
for pair in stage1_candidates:
    stage1_ids.append(pair[0])

reranked = []
for doc_id in stage1_ids:
    if doc_id in relevant_docs:
        reranked.append(doc_id)
for doc_id in stage1_ids:
    if doc_id not in relevant_docs:
        reranked.append(doc_id)

stage1_hits = 0
for doc_id in stage1_ids:
    if doc_id in relevant_docs:
        stage1_hits += 1

final_top3 = reranked[:3]
final_hits = 0
for doc_id in final_top3:
    if doc_id in relevant_docs:
        final_hits += 1

cand_ceiling = stage1_hits / len(relevant_docs)
final_recall = final_hits / len(relevant_docs)

print("Stage-1 Top-5 pool:", stage1_ids)
print("Reranked Top-3    :", final_top3)
print(f"Stage-1 Recall@5 (Ceiling) = {cand_ceiling:.4f}")
print(f"Final   Recall@3           = {final_recall:.4f} (never exceeds ceiling!)")

# Sliding Window Chunking + Overlap + Parent Document Deduplication
def chunk_words(doc_id, words, size, overlap):
    if size <= 0 or overlap < 0 or overlap >= size:
        raise ValueError("Require size > 0 and 0 <= overlap < size (infinite loop guard!)")
    stride = size - overlap
    chunks = []
    start = 0
    chunk_idx = 0
    while start < len(words):
        end = start + size
        if end > len(words):
            end = len(words)
        chunks.append({
            "chunk_id": f"{doc_id}#c{chunk_idx}",
            "parent_id": doc_id,
            "start": start,
            "end": end,
            "length": end - start,
        })
        if end == len(words):
            break
        start += stride
        chunk_idx += 1
    return chunks

# ৯৫ শব্দের একটি Abstract তৈরি করি
words = []
for i in range(95):
    words.append(f"w{i}")

chunks = chunk_words("doc_7", words, size=40, overlap=10)
print(f"Total words={len(words)}, stride=30 -> {len(chunks)} chunks:")
for c in chunks:
    print(f"  {c['chunk_id']} spans [{c['start']}, {c['end']}) len={c['length']}")

# Parent Max-score Deduplication: একই Paper-এর ৩টি Chunk শীর্ষে এলে সংকুচিত করা
chunk_hits = [
    ("doc_7#c0", "doc_7", 0.91),
    ("doc_7#c1", "doc_7", 0.87),
    ("doc_7#c2", "doc_7", 0.84),
    ("doc_12#c0", "doc_12", 0.80),
    ("doc_19#c1", "doc_19", 0.76),
]

best_parent = {}
for cid, pid, score in chunk_hits:
    if pid not in best_parent or score > best_parent[pid]:
        best_parent[pid] = score

def parent_key(item):
    return (-item[1], int(item[0].split("_")[1]))

doc_ranking = sorted(best_parent.items(), key=parent_key)
print("Unique Parent Doc Ranking:", doc_ranking)

# Reciprocal Rank Fusion (RRF, c = 60): কীভাবে দুটি Rank-2 একটি Rank-1-কে ছাড়িয়ে যায়!
def rrf_fuse(branches, c=60):
    scores = {}
    for branch in branches:
        # একই শাখায় Duplicate Document ID কঠোরভাবে নিষিদ্ধ!
        if len(branch) != len(set(branch)):
            raise ValueError("Duplicate doc_id detected inside a single branch!")
        for rank_pos, doc_id in enumerate(branch, start=1):
            scores[doc_id] = scores.get(doc_id, 0.0) + (1.0 / (c + rank_pos))

    def sort_key(item):
        return (-item[1], item[0])

    return sorted(scores.items(), key=sort_key)

# শাখা ১ (Lexical): ["A", "C"] | শাখা ২ (Dense): ["B", "C"]
# "A" শুধু শাখা ১-এ Rank 1; "B" শুধু শাখা ২-এ Rank 1; "C" উভয় শাখায় Rank 2!
fused = rrf_fuse([["A", "C"], ["B", "C"]], c=60)
for pos, (doc_id, sc) in enumerate(fused, 1):
    print(f"Fused Rank {pos}: doc={doc_id} | RRF_score={sc:.6f}")

# RRF Constant c-এর প্রভাব (Rank 1 বনাম Rank 10-এর অনুপাত):
for c_val in [10, 60, 120]:
    r1 = 1.0 / (c_val + 1)
    r10 = 1.0 / (c_val + 10)
    print(f"c={c_val:3d}: Rank1={r1:.5f} | Rank10={r10:.5f} | Ratio(R1/R10)={r1/r10:.2f}x")

# Pre-filtering বনাম Post-filtering + Deletion Tombstone Guard
# স্কোর অনুযায়ী সাজানো ৪টি Document, কিন্তু কেবল {"C", "D"} বৈধ এবং "D" মুছে ফেলা (Deleted)!
ranked_global = [("A", 0.90), ("B", 0.80), ("C", 0.70), ("D", 0.60)]
eligible = {"C", "D"}
k = 2

# ১) Post-filter (ভুল বা ঝুঁকিপূর্ণ ক্রম): আগে Global Top-2, তারপর Filter!
post_filtered = []
for pair in ranked_global[:k]:
    if pair[0] in eligible:
        post_filtered.append(pair)

# ২) Pre-filter (সঠিক ক্রম): আগে Eligible সেটে সীমাবদ্ধ করে তারপর Top-2!
pre_filtered = []
for pair in ranked_global:
    if pair[0] in eligible:
        pre_filtered.append(pair)
        if len(pre_filtered) == k:
            break

# ৩) Deletion Tombstone সহ Pre-filter (ধরুন "D" ডিলিট করা হয়েছে)
tombstones = {"D"}
active_pre_filtered = []
for pair in ranked_global:
    doc_id = pair[0]
    if doc_id in eligible and doc_id not in tombstones:
        active_pre_filtered.append(pair)
        if len(active_pre_filtered) == k:
            break

print("Post-filter Top-2 (crowded out!):", post_filtered, "| count =", len(post_filtered))
print("Pre-filter  Top-2 (complete!)   :", pre_filtered, "| count =", len(pre_filtered))
print("Pre-filter + Tombstone({'D'})   :", active_pre_filtered)

import math
import re

# Interview Readiness: শূন্য থেকে সম্পূর্ণ Mini Retrieval + RRF + Metrics + Edge-case Suite!
def tokenize(text):
    out = []
    for tok in re.findall(r"[A-Za-z0-9]+", text):
        out.append(tok.lower())
    return out

def rrf_fuse(branches, c=60):
    scores = {}
    for branch in branches:
        if len(branch) != len(set(branch)):
            raise ValueError("Duplicate ID in branch")
        for r, doc_id in enumerate(branch, 1):
            scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (c + r)
    def key_fn(item):
        return (-item[1], int(item[0]))
    return sorted(scores.items(), key=key_fn)

def evaluate_topk(ranked_ids, relevant_set, k):
    if not relevant_set or len(ranked_ids) != len(set(ranked_ids)):
        raise ValueError("Invalid ranking or empty relevant set")
    hits = 0
    first_rank = None
    dcg = 0.0
    for pos, doc_id in enumerate(ranked_ids[:k], 1):
        if doc_id in relevant_set:
            hits += 1
            if first_rank is None:
                first_rank = pos
            dcg += 1.0 / math.log2(pos + 1)
    ideal_n = k if k < len(relevant_set) else len(relevant_set)
    idcg = 0.0
    for pos in range(1, ideal_n + 1):
        idcg += 1.0 / math.log2(pos + 1)
    return {
        "recall": round(hits / len(relevant_set), 4),
        "mrr": round((1.0 / first_rank) if first_rank else 0.0, 4),
        "ndcg": round(dcg / idcg, 4),
    }

# ১) বাংলা OOV Query টেস্ট
oov_tokens = tokenize("ক্যানসার চিকিৎসা")
print("Bangla query ASCII tokens (must be empty):", oov_tokens)

# ২) Numeric Tie-breaking + RRF Fusion টেস্ট
fused = rrf_fuse([["10", "2"], ["7", "2"]], c=60)
fused_ids = []
for pair in fused:
    fused_ids.append(pair[0])
print("Fused IDs (2 wins consensus, 7 beats 10 on tie):", fused_ids)

# ৩) Metrics যাচাই (relevant={"2", "10"}, k=3)
m = evaluate_topk(fused_ids, {"2", "10"}, k=3)
print("Evaluation @3:", m)
